#include <iostream>
#include <vector>

using namespace std;

/**
 * Problem: 21944 - Power Crisis
 * 
 * 解題思路：
 * 1. 這是一個約瑟夫環問題 (Josephus Problem) 的變體。
 * 2. 有 N 個區域，從 1 號開始關閉，然後每隔 m 個關閉一個。
 * 3. 目標是找到最小的 m，使得 13 號區域是最後一個被關閉的。
 * 4. 由於 N 的範圍很小 (13 <= N < 100)，我們可以從 m = 1 開始模擬，直到找到滿足條件的 m。
 * 5. 模擬過程：
 *    - 使用一個向量存儲所有區域 1 到 N。
 *    - 首先移除 1 號。
 *    - 然後按照步長 m 重複移除，直到只剩下一個區域。
 *    - 檢查最後剩下的區域是否為 13。
 */

bool check(int n, int m) {
    vector<int> regions;
    for (int i = 1; i <= n; i++) regions.push_back(i);

    int curr = 0;
    regions.erase(regions.begin()); // 首先移除 1 號

    while (regions.size() > 1) {
        curr = (curr + m - 1) % regions.size();
        if (regions[curr] == 13) return false; // 13 號不能提前被移除
        regions.erase(regions.begin() + curr);
    }
    return regions[0] == 13;
}

int main() {
    int n;
    while (cin >> n && n != 0) {
        for (int m = 1; ; m++) {
            if (check(n, m)) {
                cout << m << endl;
                break;
            }
        }
    }
    return 0;
}
